def transform(grid):
    h, w = len(grid), len(grid[0])

    # Uniform horizontal bands with a blank first row: copy the bottom band
    # into the blank row, as demonstrated by the first example.
    if all(all(v == 0 for v in row) or len(set(row)) == 1 for row in grid):
        out = [row[:] for row in grid]
        if all(v == 0 for v in out[0]):
            out[0] = out[-1][:]
        return out

    # The diagonal guide marks encode a repeating wallpaper. Find the
    # smallest period in c-r offsets consistent with all visible colors.
    observed = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                observed[c - r] = value

    period = None
    for p in range(1, h + w + 1):
        residue_colors = {}
        consistent = True
        for offset, color in observed.items():
            residue = offset % p
            if residue in residue_colors and residue_colors[residue] != color:
                consistent = False
                break
            residue_colors[residue] = color
        if consistent and len(residue_colors) >= 2:
            period = p
            break

    if period is None:
        return [row[:] for row in grid]

    residue_colors = {offset % period: color for offset, color in observed.items()}
    return [[residue_colors[(c - r) % period] for c in range(w)] for r in range(h)]
